(576481, 59695, 14986, '<td valign="top">hehe...cute.</td>', 'hehe...cute.', '2004-02-11 12:53:28.000000', NULL, 1),
(576484, 58671, 14986, '<td valign="top">This is a really cool photo.   I''m not even sure why I like it!   I like the pose, like the lighting.  I think it''s because someone actually sat in the middle of the street for this shot (probably pretty late), and I can just envision the neighbors...."What in the world are they doing out there?"</td>', 'This is a really cool photo.   I''m not even sure why I like it!   I like the pose, like the lighting.  I think it''s because someone actually sat in the middle of the street for this shot (probably pretty late), and I can just envision the neighbors...."What in the world are they doing out there?"', '2004-02-11 12:56:32.000000', NULL, 1),
(576485, 59029, 16106, '<td valign="top">I like the composition and the colors, but when I blew it up the blisters on the statue jumped out at me. They look like pustules! I like the lighting and the DOF gives that sense of letting go but the surface of the statue cost the image points.</td>', 'I like the composition and the colors, but when I blew it up the blisters on the statue jumped out at me. They look like pustules! I like the lighting and the DOF gives that sense of letting go but the surface of the statue cost the image points.', '2004-02-11 12:57:27.000000', NULL, 1),
(576486, 59701, 13136, '<td valign="top">Where''s the water? Nice shot.</td>', 'Where''s the water? Nice shot.', '2004-02-11 12:58:33.000000', NULL, 1),
(576487, 58917, 11895, '<td valign="top">pretty dark</td>', 'pretty dark', '2004-02-11 13:00:04.000000', NULL, 1),
