(577184, 58951, 15242, '<td valign="top">Great shot, but nothing is really letting go.</td>', 'Great shot, but nothing is really letting go.', '2004-02-11 21:21:50.000000', NULL, 1),
(577185, 59701, 16230, '<td valign="top">Very nice. My favorite in this challenge.</td>', 'Very nice. My favorite in this challenge.', '2004-02-11 21:21:52.000000', NULL, 1),
(577186, 59181, 15242, '<td valign="top">Not well taken and not sure how it meets the challenge.  I guess I don''t get it.</td>', 'Not well taken and not sure how it meets the challenge.  I guess I don''t get it.', '2004-02-11 21:22:35.000000', NULL, 1),
(577187, 59519, 15242, '<td valign="top">The subject of the shot is easily missed in this, and is just a small part of the picture.  That makes it very snap shot ish.</td>', 'The subject of the shot is easily missed in this, and is just a small part of the picture.  That makes it very snap shot ish.', '2004-02-11 21:23:51.000000', NULL, 1),
(577190, 58625, 10819, '<td valign="top">nice added effect with the ''tears'' ;)</td>', 'nice added effect with the ''tears'' ;)', '2004-02-11 21:24:35.000000', NULL, 1),
(577191, 59313, 15242, '<td valign="top">Good capture of emotion.  I little noise in the black, but good shot.</td>', 'Good capture of emotion.  I little noise in the black, but good shot.', '2004-02-11 21:24:38.000000', NULL, 1),
(577194, 59701, 772, '<td valign="top">Excellent work... letting go of some thoughts and stresses associated with a long day... relaxation is finally at hand.  A glass of merlot... Enya on the CD player... hot water... the light from candles... a nice escape :)<br/> <br/>I like this as a black and white.  It works well.  Some sepia toning here could also add some nice ''warmth'' to the image to support the ''relaxation'' theme as well...  Excellent work :)<br/></td>', 'Excellent work... letting go of some thoughts and stresses associated with a long day... relaxation is finally at hand.  A glass of merlot... Enya on the CD player... hot water... the light from candles... a nice escape :) I like this as a black and white.  It works well.  Some sepia toning here could also add some nice ''warmth'' to the image to support the ''relaxation'' theme as well...  Excellent work :)', '2004-02-11 21:26:14.000000', NULL, 1),
(577197, 58564, 15242, '<td valign="top">I have no clue what this is.  If this were an absract art challenge I''d vote this high because I like the colors and the shapes, but this doesn''t say let go to me.</td>', 'I have no clue what this is.  If this were an absract art challenge I''d vote this high because I like the colors and the shapes, but this doesn''t say let go to me.', '2004-02-11 21:28:03.000000', NULL, 1),
(577199, 59660, 327, '<td valign="top">Very cool affect. I really like this. Good job.</td>', 'Very cool affect. I really like this. Good job.', '2004-02-11 21:29:03.000000', NULL, 1),
(577203, 59068, 327, '<td valign="top">I like this shot...it''s emotionally charged. I think the light/...and or levels/gamma could of been adjusted to improve the balance. Good entry...best of luck.</td>', 'I like this shot...it''s emotionally charged. I think the light/...and or levels/gamma could of been adjusted to improve the balance. Good entry...best of luck.', '2004-02-11 21:31:11.000000', NULL, 1),
(577205, 58978, 15242, '<td valign="top">Too small and blurry.</td>', 'Too small and blurry.', '2004-02-11 21:32:00.000000', NULL, 1),
(577206, 59417, 327, '<td valign="top">clever, creative, good color, good entry.</td>', 'clever, creative, good color, good entry.', '2004-02-11 21:32:06.000000', NULL, 1),
(577207, 59670, 17041, '<td valign="top">Great laugh!  but I''m missing the connection.  I do wonder how you got the anole to stay still...</td>', 'Great laugh!  but I''m missing the connection.  I do wonder how you got the anole to stay still...', '2004-02-11 21:32:16.000000', NULL, 1),
(577209, 58837, 15242, '<td valign="top">Nice effect, but... crop off that part on the bottom that looks like a corner and sharpen it a bit.</td>', 'Nice effect, but... crop off that part on the bottom that looks like a corner and sharpen it a bit.', '2004-02-11 21:33:12.000000', NULL, 1),
(577210, 59047, 327, '<td valign="top">He knows how to relax.....and the right spot. Geeezzz that water right there is COLD 365 days a year.Good composition and dof.</td>', 'He knows how to relax.....and the right spot. Geeezzz that water right there is COLD 365 days a year.Good composition and dof.', '2004-02-11 21:33:42.000000', NULL, 1),
(577211, 59494, 15242, '<td valign="top">Good close up shor, but it doesn''t say letting go to me.</td>', 'Good close up shor, but it doesn''t say letting go to me.', '2004-02-11 21:33:59.000000', NULL, 1),
(577212, 59668, 327, '<td valign="top">Emotionally charged shot......the little stick cross, leather glove..........plus the great tones.......good good shot. Bravo.</td>', 'Emotionally charged shot......the little stick cross, leather glove..........plus the great tones.......good good shot. Bravo.', '2004-02-11 21:34:47.000000', NULL, 1),
(577216, 58799, 15242, '<td valign="top">I''m voting you well because I''ve got the other flower shot that is tanking on this one...  Good macro but the color of the flower seems dull.</td>', 'I''m voting you well because I''ve got the other flower shot that is tanking on this one...  Good macro but the color of the flower seems dull.', '2004-02-11 21:36:13.000000', NULL, 1),
