(578044, 58991, 16695, '<td valign="top">I like how you''ve composed the elements here, especially how the hand is small and based at the bottom center. However, it''s an action of "letting go", not a "feeling" as the contest specified. Oh well. Still a pleasant photo. :)</td>', 'I like how you''ve composed the elements here, especially how the hand is small and based at the bottom center. However, it''s an action of "letting go", not a "feeling" as the contest specified. Oh well. Still a pleasant photo. :)', '2004-02-12 13:31:42.000000', NULL, 1),
(578045, 59658, 16408, '<td valign="top">very good interpretation of the theme</td>', 'very good interpretation of the theme', '2004-02-12 13:32:22.000000', NULL, 1),
(578047, 59675, 16408, '<td valign="top">very colorful and fits the theme nicely</td>', 'very colorful and fits the theme nicely', '2004-02-12 13:34:22.000000', NULL, 1),
(578053, 59648, 13759, '<td valign="top">This focus was great at this subject. To me it confuses a bit. It´s hard to view clearly the principal subject. It is a great shoot. I wish you had used the rule of thirds on it to clarify your subject.</td>', 'This focus was great at this subject. To me it confuses a bit. It´s hard to view clearly the principal subject. It is a great shoot. I wish you had used the rule of thirds on it to clarify your subject.', '2004-02-12 13:38:45.000000', NULL, 1),
