(578061, 59033, 16408, '<td valign="top">pretty good pic except for the snow being overexposed, expresses the theme nicely and the title certainly captures the spirit of it</td>', 'pretty good pic except for the snow being overexposed, expresses the theme nicely and the title certainly captures the spirit of it', '2004-02-12 13:48:16.000000', NULL, 1),
