(578069, 58841, 11467, '<td valign="top">Well done. <br/>I like how you look for a while you see more &amp; more details</td>', 'Well done. I like how you look for a while you see more & more details', '2004-02-12 14:05:03.000000', NULL, 1),
(578070, 59660, 16695, '<td valign="top">That''s some really interesting lighting you used (assuming this hasn''t been tweaked.)  I look forward to reading the description and techniques for it.  Compositionally, you''ve captured a lot of movement and action. However, for a "feeling" of letting go, I''d imagine the car farther along with the streaks behind it.  *shrug* Still fun.</td>', 'That''s some really interesting lighting you used (assuming this hasn''t been tweaked.)  I look forward to reading the description and techniques for it.  Compositionally, you''ve captured a lot of movement and action. However, for a "feeling" of letting go, I''d imagine the car farther along with the streaks behind it.  *shrug* Still fun.', '2004-02-12 14:05:07.000000', NULL, 1),
(578071, 59069, 11467, '<td valign="top">Nice photo</td>', 'Nice photo', '2004-02-12 14:05:25.000000', NULL, 1),
(578072, 59469, 13759, '<td valign="top">Very hard light. This hurt my eyes. It seems to be opened with curves or brightness. Then the overexposure onthe balls are noticeable faster. There are a bit of a strange tones here too over the green balls.</td>', 'Very hard light. This hurt my eyes. It seems to be opened with curves or brightness. Then the overexposure onthe balls are noticeable faster. There are a bit of a strange tones here too over the green balls.', '2004-02-12 14:06:02.000000', NULL, 1),
(578075, 59417, 11467, '<td valign="top">Funny!  A good idea. Unfortunate you can see the cut out outlines around the leggs</td>', 'Funny!  A good idea. Unfortunate you can see the cut out outlines around the leggs', '2004-02-12 14:07:18.000000', NULL, 1),
(578076, 58978, 11467, '<td valign="top">Wow , Cool. <br/>A shame it is so small</td>', 'Wow , Cool. A shame it is so small', '2004-02-12 14:07:39.000000', NULL, 1),
(578078, 59374, 16695, '<td valign="top">Pleasant and relaxing image, good idea and good lighting.  Speaking of lighting, I''d move that lamp up a couple inches and this would be great. ;)</td>', 'Pleasant and relaxing image, good idea and good lighting.  Speaking of lighting, I''d move that lamp up a couple inches and this would be great. ;)', '2004-02-12 14:08:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(578079, 58642, 11467, '<td valign="top">Nice, Perhaps a bit overexposed &amp; blown out on the edges</td>', 'Nice, Perhaps a bit overexposed & blown out on the edges', '2004-02-12 14:08:53.000000', NULL, 1),
(578080, 59636, 13759, '<td valign="top">It´s like my first idea to this challenge.  Good shot. I think you can improve the capture angle. It´s almost a silhouette. A bit more dark or light will be good. The mid tone almost black lead me to think that it was a lack.</td>', 'It´s like my first idea to this challenge.  Good shot. I think you can improve the capture angle. It´s almost a silhouette. A bit more dark or light will be good. The mid tone almost black lead me to think that it was a lack.', '2004-02-12 14:10:13.000000', NULL, 1),
(578082, 58657, 13759, '<td valign="top">Something really important in photography is the title. It can improve the message of the photo, explaining it or adding to it. Or can leave you desperated! What this is, can you ask. How I can´t though it. Are commom thoughs that we make when read the titles after looking the picture. But nothing is better than an image that said all about itself. Looking to your picture I can´t understand your title. Think about it. Good Luck.</td>', 'Something really important in photography is the title. It can improve the message of the photo, explaining it or adding to it. Or can leave you desperated! What this is, can you ask. How I can´t though it. Are commom thoughs that we make when read the titles after looking the picture. But nothing is better than an image that said all about itself. Looking to your picture I can´t understand your title. Think about it. Good Luck.', '2004-02-12 14:14:12.000000', NULL, 1),
(578083, 59108, 16408, '<td valign="top">I''d try to lighten it up a bit so you could see more of the shoreline</td>', 'I''d try to lighten it up a bit so you could see more of the shoreline', '2004-02-12 14:14:17.000000', NULL, 1),
(578084, 59045, 11467, '<td valign="top">Please choose 1:<br/>A. A different coloured pen would contrast better with the background.<br/>B. A different coloured background would contrast better with the pen.</td>', 'Please choose 1:A. A different coloured pen would contrast better with the background.B. A different coloured background would contrast better with the pen.', '2004-02-12 14:15:06.000000', NULL, 1),
(578085, 59660, 16408, '<td valign="top">cool idea but the background colors are too drab</td>', 'cool idea but the background colors are too drab', '2004-02-12 14:15:14.000000', NULL, 1),
(578086, 59631, 13759, '<td valign="top">It says notthing to me about letting go. Can I missinterpret the letting go expression?</td>', 'It says notthing to me about letting go. Can I missinterpret the letting go expression?', '2004-02-12 14:15:17.000000', NULL, 1),
(578087, 59425, 11467, '<td valign="top">I think the rings should be in focus</td>', 'I think the rings should be in focus', '2004-02-12 14:16:33.000000', NULL, 1),
(578088, 59666, 13759, '<td valign="top">Single light source, simple composition addictive shapes. A basic approach to this challenge. Not bad at all, not sttuning. Photography is clear and well done.</td>', 'Single light source, simple composition addictive shapes. A basic approach to this challenge. Not bad at all, not sttuning. Photography is clear and well done.', '2004-02-12 14:17:03.000000', NULL, 1),
(578089, 59699, 11467, '<td valign="top">Huh??? Cant seem to link this to letting go.</td>', 'Huh??? Cant seem to link this to letting go.', '2004-02-12 14:17:35.000000', NULL, 1),
(578090, 59636, 16408, '<td valign="top">can''t tell what that stuff in the upper right is, if it''s not important to the picture a step or two to the right would have given you an angle without it</td>', 'can''t tell what that stuff in the upper right is, if it''s not important to the picture a step or two to the right would have given you an angle without it', '2004-02-12 14:17:53.000000', NULL, 1),
(578092, 59550, 11467, '<td valign="top">Lost me there!</td>', 'Lost me there!', '2004-02-12 14:18:52.000000', NULL, 1),
(578093, 59561, 11467, '<td valign="top">Letting Go?</td>', 'Letting Go?', '2004-02-12 14:19:07.000000', NULL, 1),
(578094, 58738, 13759, '<td valign="top">There are a lot of issues over this picture. The light is overexposed in some flowers parts, focus is not well done. Nothing against people the like soft focus os bokeh style, but this fucos are simply a bad focus. May be your camera shake had done this. Try to use a tripod in shutter speeds below 1/60. Composition itself is not bad.</td>', 'There are a lot of issues over this picture. The light is overexposed in some flowers parts, focus is not well done. Nothing against people the like soft focus os bokeh style, but this fucos are simply a bad focus. May be your camera shake had done this. Try to use a tripod in shutter speeds below 1/60. Composition itself is not bad.', '2004-02-12 14:20:25.000000', NULL, 1),
(578095, 59446, 11467, '<td valign="top">I think the hand should be above the top film.</td>', 'I think the hand should be above the top film.', '2004-02-12 14:20:51.000000', NULL, 1),
(578096, 59687, 11467, '<td valign="top">Took me a while to work this one out. ROFL<br/>Not too good for the trousers</td>', 'Took me a while to work this one out. ROFLNot too good for the trousers', '2004-02-12 14:23:33.000000', NULL, 1),
(578097, 59545, 13759, '<td valign="top">Sometimes I want to do the same. Good shoot. I like it very much. If you are interested, I had some issues the can enhance it a bit. The first idea of Letting Go of it All, is free yourself of those chains to your life cycle, not? Well, in this regard, the bars visions are strange. Other issue is about the exposure that has ovexposed parts in the grid and at CD on basket. Good Lucky.</td>', 'Sometimes I want to do the same. Good shoot. I like it very much. If you are interested, I had some issues the can enhance it a bit. The first idea of Letting Go of it All, is free yourself of those chains to your life cycle, not? Well, in this regard, the bars visions are strange. Other issue is about the exposure that has ovexposed parts in the grid and at CD on basket. Good Lucky.', '2004-02-12 14:25:17.000000', NULL, 1),
(578098, 59675, 13759, '<td valign="top">And the oscar letting goes to...</td>', 'And the oscar letting goes to...', '2004-02-12 14:26:07.000000', NULL, 1),
(578099, 59435, 11467, '<td valign="top">Pretty dark</td>', 'Pretty dark', '2004-02-12 14:28:12.000000', NULL, 1),
(578100, 59687, 13759, '<td valign="top">What such thing do you eat? Stay away from hot places! You can explode.</td>', 'What such thing do you eat? Stay away from hot places! You can explode.', '2004-02-12 14:28:46.000000', NULL, 1),
(578101, 58733, 11467, '<td valign="top">The frame is cropped too close. it shouldn''t touch the beak</td>', 'The frame is cropped too close. it shouldn''t touch the beak', '2004-02-12 14:29:01.000000', NULL, 1),
(578104, 59124, 13759, '<td valign="top">What can we saw the connection between letting go theme and this picture?</td>', 'What can we saw the connection between letting go theme and this picture?', '2004-02-12 14:29:49.000000', NULL, 1),
(578106, 59126, 13759, '<td valign="top">A new fashion. The bow fashion at DPC. First were the water drops... then now, with the Zodiac challenge, people discover the bows. Oh, please be original.</td>', 'A new fashion. The bow fashion at DPC. First were the water drops... then now, with the Zodiac challenge, people discover the bows. Oh, please be original.', '2004-02-12 14:31:59.000000', NULL, 1),
(578107, 59626, 11467, '<td valign="top">Extra point for originality!<br/>Unfortunately a little hard to see the hair. Perhaps a light background would contrast better with the hair</td>', 'Extra point for originality!Unfortunately a little hard to see the hair. Perhaps a light background would contrast better with the hair', '2004-02-12 14:32:08.000000', NULL, 1),
(578108, 59185, 13759, '<td valign="top">Please, let the note goes to my pocket!</td>', 'Please, let the note goes to my pocket!', '2004-02-12 14:33:01.000000', NULL, 1),
(578109, 59561, 13759, '<td valign="top">This picture are awesome. Good green tones on grass. It has nothing to do with the challenge theme. Will be low scored. But a great picture.</td>', 'This picture are awesome. Good green tones on grass. It has nothing to do with the challenge theme. Will be low scored. But a great picture.', '2004-02-12 14:34:30.000000', NULL, 1),
(578114, 59495, 13759, '<td valign="top">Oh, this is very noisy. Interesting how noise can improve or degrade an image. But it makes better B&amp;W pictures. You neet to use NeatImage or low ISO setting.</td>', 'Oh, this is very noisy. Interesting how noise can improve or degrade an image. But it makes better B&W pictures. You neet to use NeatImage or low ISO setting.', '2004-02-12 14:48:26.000000', NULL, 1),
(578116, 59433, 13759, '<td valign="top">It´s a great picture. Very special to US of DPC. But I can´t link it to this challenge. I repeat it´s a good picture. Very well done.</td>', 'It´s a great picture. Very special to US of DPC. But I can´t link it to this challenge. I repeat it´s a good picture. Very well done.', '2004-02-12 14:52:23.000000', NULL, 1),
(578118, 59431, 15982, '<td valign="top">Wonderful picture and nice take on the challenge. I am definitely more inclined towards the optimistic entries in this challenge.</td>', 'Wonderful picture and nice take on the challenge. I am definitely more inclined towards the optimistic entries in this challenge.', '2004-02-12 14:55:08.000000', NULL, 1),
(578119, 59484, 15982, '<td valign="top">What an awesome tree. I love your take on the challenge. And what a great sunset!</td>', 'What an awesome tree. I love your take on the challenge. And what a great sunset!', '2004-02-12 14:57:13.000000', NULL, 1),
(578120, 59687, 15539, '<td valign="top">HAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHA</td>', 'HAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHAHA', '2004-02-12 14:57:51.000000', NULL, 1),
(578122, 59697, 15982, '<td valign="top">Cool idea! I like you interpretation on the challenge.<br/>For some reason I find a litte too much distraction in the picture. Maybe I just too much light, but my eye wonders around quite a bit. All in all, a nice take! Good luck!</td>', 'Cool idea! I like you interpretation on the challenge.For some reason I find a litte too much distraction in the picture. Maybe I just too much light, but my eye wonders around quite a bit. All in all, a nice take! Good luck!', '2004-02-12 14:59:06.000000', NULL, 1),
(578123, 59453, 15539, '<td valign="top">Psycho - Kenetics?</td>', 'Psycho - Kenetics?', '2004-02-12 14:59:29.000000', NULL, 1),
(578125, 58837, 15982, '<td valign="top">THAT''S definitely a feeling of letting go. Cool picture!!! And nice hang time! Good luck!</td>', 'THAT''S definitely a feeling of letting go. Cool picture!!! And nice hang time! Good luck!', '2004-02-12 15:00:32.000000', NULL, 1),
(578129, 58625, 13749, '<td valign="top">"can''t go through with this is"?  unless i''m missing something, seems like a bit of a grammatical error.  i think the picture might''ve come out slightly better if you had either torn off the piece on the very left, or used a type of notebook/composition that better complemented the rings (maybe just because i''m still in school - but the choice of notebook makes me think "student").  still, a good photograph with a nice use of lighting.  the tear drops are a good thought, as well.</td>', '"can''t go through with this is"?  unless i''m missing something, seems like a bit of a grammatical error.  i think the picture might''ve come out slightly better if you had either torn off the piece on the very left, or used a type of notebook/composition that better complemented the rings (maybe just because i''m still in school - but the choice of notebook makes me think "student").  still, a good photograph with a nice use of lighting.  the tear drops are a good thought, as well.', '2004-02-12 15:06:13.000000', NULL, 1),
(578130, 58843, 15982, '<td valign="top">Awesome take on the challenge. I actually thought of something very similar. I hope you get good scores, but from what I understand about peoples interpretation of the challenge from the forums and my own entry, you are probably getting some undeserved low scores.<br/>My feeling about your picture:<br/>I think you could have left out the light behind your subject to emphasize him a little more. The backgrounds competes for the attention of my eye a little. At the same time, I think the light behind is a decent idea, maybe just too much of it or something. The outline of the mat behind the bottom two candles is a little distracting as well. I am big about analyzing on where my eye goes in the picture. Good luck! 8</td>', 'Awesome take on the challenge. I actually thought of something very similar. I hope you get good scores, but from what I understand about peoples interpretation of the challenge from the forums and my own entry, you are probably getting some undeserved low scores.My feeling about your picture:I think you could have left out the light behind your subject to emphasize him a little more. The backgrounds competes for the attention of my eye a little. At the same time, I think the light behind is a decent idea, maybe just too much of it or something. The outline of the mat behind the bottom two candles is a little distracting as well. I am big about analyzing on where my eye goes in the picture. Good luck! 8', '2004-02-12 15:07:18.000000', NULL, 1),
(578135, 59668, 15982, '<td valign="top">The colors and textures are incredible in this picture. Good luck!</td>', 'The colors and textures are incredible in this picture. Good luck!', '2004-02-12 15:08:52.000000', NULL, 1),
(578137, 59465, 15982, '<td valign="top">I love it! I have been somewhat biased towards the more optimistic pictures because of the shortage of them! I hope that the majority of voters understands how this is letting go. They sure don''t understand mine!<br/>Good luck!!! 9</td>', 'I love it! I have been somewhat biased towards the more optimistic pictures because of the shortage of them! I hope that the majority of voters understands how this is letting go. They sure don''t understand mine!Good luck!!! 9', '2004-02-12 15:11:17.000000', NULL, 1),
(578138, 58920, 15982, '<td valign="top">Nice title! Really emphasizes the picture and the person standing there. The glare around the sun is a little bit distracting though. Other than that, this is an awesome picture! 9</td>', 'Nice title! Really emphasizes the picture and the person standing there. The glare around the sun is a little bit distracting though. Other than that, this is an awesome picture! 9', '2004-02-12 15:12:43.000000', NULL, 1),
(578140, 59643, 15982, '<td valign="top">Really cool idea! Sometimes a title tells the whole story and the picture just adds substance. Nice job! 10</td>', 'Really cool idea! Sometimes a title tells the whole story and the picture just adds substance. Nice job! 10', '2004-02-12 15:13:45.000000', NULL, 1),
(578141, 59645, 15982, '<td valign="top">Really incredible shot!<br/>I really like it! Good luck! 9</td>', 'Really incredible shot!I really like it! Good luck! 9', '2004-02-12 15:14:48.000000', NULL, 1),
(578142, 59654, 16703, '<td valign="top">i love this picture... going to become one of my favorites.. the person and his expression is trully remarkable.. and how he posed with the cigarette in his hands.. i generally have hard time explaning what i like in a photograph, but i like to say this one is really a winner for me.. i gave it a ten, my only ten in this challenge. i think you well deserved it... but as far as making a critique: his white shirt is a little overexposed and the background is a little busy, might have been better blurred out.. and may be i would have liked some more detail in the eyes...</td>', 'i love this picture... going to become one of my favorites.. the person and his expression is trully remarkable.. and how he posed with the cigarette in his hands.. i generally have hard time explaning what i like in a photograph, but i like to say this one is really a winner for me.. i gave it a ten, my only ten in this challenge. i think you well deserved it... but as far as making a critique: his white shirt is a little overexposed and the background is a little busy, might have been better blurred out.. and may be i would have liked some more detail in the eyes...', '2004-02-12 15:15:48.000000', NULL, 1),
(578148, 59082, 16703, '<td valign="top">i really like this picture.. i gave it an 8.. but increaasing it to a 9...since this picture captured the feeling of letting go the best for me at least out of all the pictures in this challenge... good work... only improvement i can suggest is to make it a little brighter...</td>', 'i really like this picture.. i gave it an 8.. but increaasing it to a 9...since this picture captured the feeling of letting go the best for me at least out of all the pictures in this challenge... good work... only improvement i can suggest is to make it a little brighter...', '2004-02-12 15:18:41.000000', NULL, 1),
(578155, 59646, 15982, '<td valign="top">Nice idea! I just feel that it is too dark to portray the feeling you are trying to get across. Maybe if you are more sad about letting go of your childhood (which is understandable, as I can''t do that!), but I would still use more light, just emphasize the blue hues in the picture.</td>', 'Nice idea! I just feel that it is too dark to portray the feeling you are trying to get across. Maybe if you are more sad about letting go of your childhood (which is understandable, as I can''t do that!), but I would still use more light, just emphasize the blue hues in the picture.', '2004-02-12 15:28:33.000000', NULL, 1),
(578169, 59673, 9295, '<td valign="top">This is disappointing because it is a cute idea but the photo itself is not at all appealing.  You might consider using black and white to tone down the backdrop which doesn''t add at all to the subject.  Also, to conform a little more to the theme of the challenge, you probably should have waited for that split second when the dog finally released the toy.</td>', 'This is disappointing because it is a cute idea but the photo itself is not at all appealing.  You might consider using black and white to tone down the backdrop which doesn''t add at all to the subject.  Also, to conform a little more to the theme of the challenge, you probably should have waited for that split second when the dog finally released the toy.', '2004-02-12 16:01:18.000000', NULL, 1),
(578171, 59070, 16695, '<td valign="top">I like the relaxing concept, but I think you could have done more with this.  Perhaps working a bit harder to keep the interior steady and let the movement of elements outside create the motion.  Just my .02. Good luck!</td>', 'I like the relaxing concept, but I think you could have done more with this.  Perhaps working a bit harder to keep the interior steady and let the movement of elements outside create the motion.  Just my .02. Good luck!', '2004-02-12 16:02:21.000000', NULL, 1),
(578173, 59561, 16695, '<td valign="top">Pretty picture, but I''m not really feeling anything towards "letting go." Relaxing, perhaps... but it''s a stretch.</td>', 'Pretty picture, but I''m not really feeling anything towards "letting go." Relaxing, perhaps... but it''s a stretch.', '2004-02-12 16:06:14.000000', NULL, 1),
(578174, 59236, 9295, '<td valign="top">Great idea for the challenge but I think it would work better if the hand were more in focus and I don''t really care for the off-white background color.  A little tweaking and this might have been one of the better submissions, since the framing and composition are good and the timing of the capture is right on.</td>', 'Great idea for the challenge but I think it would work better if the hand were more in focus and I don''t really care for the off-white background color.  A little tweaking and this might have been one of the better submissions, since the framing and composition are good and the timing of the capture is right on.', '2004-02-12 16:07:04.000000', NULL, 1),
(578177, 58843, 9295, '<td valign="top">I like this a lot...except for the candles which I realize are important to the mood but their brightness is somewhat distracting since the eye keeps wanting to wander down there instead of on your focal point.  Maybe red candles...?  Anyway, what I do like is the man''s pose, the halo affect of the lighting behind him, the red tones and the theme interpretation.  I gave you an 8</td>', 'I like this a lot...except for the candles which I realize are important to the mood but their brightness is somewhat distracting since the eye keeps wanting to wander down there instead of on your focal point.  Maybe red candles...?  Anyway, what I do like is the man''s pose, the halo affect of the lighting behind him, the red tones and the theme interpretation.  I gave you an 8', '2004-02-12 16:09:57.000000', NULL, 1),
(578179, 59497, 15539, '<td valign="top">I think that a lot of your voters will probably have problems understanding this picture but I think it captures a feeling that we all need to deal with at some point in time. I would guess you probably arent getting the results you want, but Im giving you a 7 because I like how this picture made me feel.</td>', 'I think that a lot of your voters will probably have problems understanding this picture but I think it captures a feeling that we all need to deal with at some point in time. I would guess you probably arent getting the results you want, but Im giving you a 7 because I like how this picture made me feel.', '2004-02-12 16:11:25.000000', NULL, 1),
(578185, 59560, 9295, '<td valign="top">This is one of my favorites of the challenge. I like the mistiness of the "ghost" as well as his pose, looking down upon his old self. Cropping the lying down body as you did makes the image in the shadows the focal point. This is done quite nicely.  I also like the radient lighting from the dark shadow on the right side of the photo to the lighter area on the left.</td>', 'This is one of my favorites of the challenge. I like the mistiness of the "ghost" as well as his pose, looking down upon his old self. Cropping the lying down body as you did makes the image in the shadows the focal point. This is done quite nicely.  I also like the radient lighting from the dark shadow on the right side of the photo to the lighter area on the left.', '2004-02-12 16:14:34.000000', NULL, 1),
(578186, 59645, 3032, '<td valign="top">Great lighting, excellent composition, very good.<br/> <br/></td>', 'Great lighting, excellent composition, very good. ', '2004-02-12 16:16:04.000000', NULL, 1),
(578187, 59658, 11467, '<td valign="top">Very nicely set up and photographed.<br/>I particularly like your idea for this challenge.</td>', 'Very nicely set up and photographed.I particularly like your idea for this challenge.', '2004-02-12 16:16:18.000000', NULL, 1),
(578189, 59666, 11467, '<td valign="top">Maybe a bit too much foreground black.</td>', 'Maybe a bit too much foreground black.', '2004-02-12 16:17:39.000000', NULL, 1),
(578190, 59661, 9295, '<td valign="top">The interesting thing about this photo (beyond the technical success) is the untold story left for the imagination to figure out.  What was let go?  Why is there regret?  Is this the hand that let something go or is it the one that was released?  Technically, the shot is beautiful.  The radiant lighting, the center placement of the hand, the deep shadow of the thumb contrasting the almost washed-out look of the top of the hand, all very appealing to this viewer. The more I look at it, the more I like it.  A 9.</td>', 'The interesting thing about this photo (beyond the technical success) is the untold story left for the imagination to figure out.  What was let go?  Why is there regret?  Is this the hand that let something go or is it the one that was released?  Technically, the shot is beautiful.  The radiant lighting, the center placement of the hand, the deep shadow of the thumb contrasting the almost washed-out look of the top of the hand, all very appealing to this viewer. The more I look at it, the more I like it.  A 9.', '2004-02-12 16:18:33.000000', NULL, 1),
(578191, 59677, 16497, '<td valign="top">interesting!</td>', 'interesting!', '2004-02-12 16:20:27.000000', NULL, 1),
(578193, 59471, 16497, '<td valign="top">i feel your pain sister.  interesting take on the challenge.</td>', 'i feel your pain sister.  interesting take on the challenge.', '2004-02-12 16:21:36.000000', NULL, 1),
(578194, 59625, 16497, '<td valign="top">looks very personal to me.</td>', 'looks very personal to me.', '2004-02-12 16:22:10.000000', NULL, 1),
(578195, 58671, 9295, '<td valign="top">I keep coming back to this shot. I don''t know exactly why.  There''s just something about it that makes me want to take another look.  It is such an interesting photo. The sepia and graininess really work here and I like that light shining so brightly in the distance.  I think what really makes this shot outstanding though is the straightness of the tire tracks in the snow and the fact that your model (you?) walked to your chair keeping as much on those tracks as is humanly possible, trying hard not to disrupt those clean lines.  Additionally, the dark sky against the white ground is an interesting change of perspective since one usually sees the sky as brighter than the ground.  Adding the suitcase was the perfect touch. I originally gave you an 8, but I''m bumping this up to a 10 just because it works on so many levels for me. Good luck.</td>', 'I keep coming back to this shot. I don''t know exactly why.  There''s just something about it that makes me want to take another look.  It is such an interesting photo. The sepia and graininess really work here and I like that light shining so brightly in the distance.  I think what really makes this shot outstanding though is the straightness of the tire tracks in the snow and the fact that your model (you?) walked to your chair keeping as much on those tracks as is humanly possible, trying hard not to disrupt those clean lines.  Additionally, the dark sky against the white ground is an interesting change of perspective since one usually sees the sky as brighter than the ground.  Adding the suitcase was the perfect touch. I originally gave you an 8, but I''m bumping this up to a 10 just because it works on so many levels for me. Good luck.', '2004-02-12 16:22:33.000000', NULL, 1),
(578196, 58909, 15920, '<td valign="top">The colors are great (though I am not in any hurry to take up residence in that neighborhood) but the focus is a little off.</td>', 'The colors are great (though I am not in any hurry to take up residence in that neighborhood) but the focus is a little off.', '2004-02-12 16:23:28.000000', NULL, 1),
(578197, 59046, 9295, '<td valign="top">I dont'' know how you''ll do in the challenge, but this is a fantastic shot.  I love it!</td>', 'I dont'' know how you''ll do in the challenge, but this is a fantastic shot.  I love it!', '2004-02-12 16:23:48.000000', NULL, 1),
