INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(580275, 59460, 1570, '<td valign="top">she is a happy looking girl, and it looks like she had a lot of fun posing for this picture... that''s all i could make out in this blurred overexposed motion... there are so many ways you can improve on this... <br/></td>', 'she is a happy looking girl, and it looks like she had a lot of fun posing for this picture... that''s all i could make out in this blurred overexposed motion... there are so many ways you can improve on this... ', '2004-02-14 22:43:57.000000', NULL, 1),
(580276, 59062, 14620, '<td valign="top">Fantastic clarity and subject!  Great shot for the challenge.  Don''t see anything I would change.</td>', 'Fantastic clarity and subject!  Great shot for the challenge.  Don''t see anything I would change.', '2004-02-14 22:44:35.000000', NULL, 1),
(580277, 58824, 14620, '<td valign="top">Very nicely composed and great lighting.  Really nice studio shot and great colors, interesting take on the challenge too.  Well done!</td>', 'Very nicely composed and great lighting.  Really nice studio shot and great colors, interesting take on the challenge too.  Well done!', '2004-02-14 22:46:08.000000', NULL, 1),
(580278, 59654, 14620, '<td valign="top">Fantastic subject and excellent B&amp;W tones!  Great detail.  This is very well done!</td>', 'Fantastic subject and excellent B&W tones!  Great detail.  This is very well done!', '2004-02-14 22:47:18.000000', NULL, 1),
(580279, 59626, 14620, '<td valign="top">Love this idea!  And I really like the lighting, it''s very warm.  Nice composition as well.</td>', 'Love this idea!  And I really like the lighting, it''s very warm.  Nice composition as well.', '2004-02-14 22:48:11.000000', NULL, 1),
(580280, 58671, 14620, '<td valign="top">What a great composition.  Seems like you had perfect timing for this shot.  Bet your neighbors thought you were a tad bit nutty though. :)  I love this, just makes me think "What''s he doing there, What''s he waiting for"  Very cool.  A little noisy/grainy but I think it adds to the feel of the picture, perhaps it was intended.</td>', 'What a great composition.  Seems like you had perfect timing for this shot.  Bet your neighbors thought you were a tad bit nutty though. :)  I love this, just makes me think "What''s he doing there, What''s he waiting for"  Very cool.  A little noisy/grainy but I think it adds to the feel of the picture, perhaps it was intended.', '2004-02-14 22:51:21.000000', NULL, 1),
(580281, 59045, 1570, '<td valign="top">this image seems overexposed and lacks quality... perhaps too much jpeg compression did that? technically it could''ve looked better if it was closer to 150K allowed here... the subject and composition don''t present any interest to me either... as far as interpretation of the challenge is concerned, it looks to me like the hand and the pen are just resting on the flat surface, that''s all...<br/></td>', 'this image seems overexposed and lacks quality... perhaps too much jpeg compression did that? technically it could''ve looked better if it was closer to 150K allowed here... the subject and composition don''t present any interest to me either... as far as interpretation of the challenge is concerned, it looks to me like the hand and the pen are just resting on the flat surface, that''s all...', '2004-02-14 22:54:21.000000', NULL, 1),
(580282, 59573, 1570, '<td valign="top">image lacks interest...<br/></td>', 'image lacks interest...', '2004-02-14 22:56:46.000000', NULL, 1),
(580283, 58738, 1570, '<td valign="top">this image seems unfocused and lacks quality... perhaps too much jpeg compression? technically it would''ve looked better if it was closer to 150K allowed... as far as interpretation of the challenge is concerned, as well as the subject and composition of this picture don''t make for very interesting viewing...<br/></td>', 'this image seems unfocused and lacks quality... perhaps too much jpeg compression? technically it would''ve looked better if it was closer to 150K allowed... as far as interpretation of the challenge is concerned, as well as the subject and composition of this picture don''t make for very interesting viewing...', '2004-02-14 23:00:36.000000', NULL, 1),
(580284, 59124, 1570, '<td valign="top">i gave this a ten, don''t really have suggestions on how to improve it... it is just so lovely...</td>', 'i gave this a ten, don''t really have suggestions on how to improve it... it is just so lovely...', '2004-02-14 23:04:03.000000', NULL, 1),
(580285, 59626, 1570, '<td valign="top">ballerina neck definitely gives this a "wow" factor... very nice interpretation of the challenge, i love the lighting, too... don''t really have any suggestions for improvement...<br/></td>', 'ballerina neck definitely gives this a "wow" factor... very nice interpretation of the challenge, i love the lighting, too... don''t really have any suggestions for improvement...', '2004-02-14 23:06:10.000000', NULL, 1),
(580286, 59062, 1570, '<td valign="top">this is one "wow" picture... don''t have any suggestions for improvement, this silhouette looks absolutely perfect to me...  <br/></td>', 'this is one "wow" picture... don''t have any suggestions for improvement, this silhouette looks absolutely perfect to me...  ', '2004-02-14 23:11:06.000000', NULL, 1),
