(580446, 59185, 15305, '<td valign="top">Great shot, great background and sense of movement in the objects. I tried something similiar but was unable to capture the elements as sharp and at the same time have the blur of movement. How did you do it?</td>', 'Great shot, great background and sense of movement in the objects. I tried something similiar but was unable to capture the elements as sharp and at the same time have the blur of movement. How did you do it?', '2004-02-15 10:43:48.000000', NULL, 1),
(580447, 59020, 15305, '<td valign="top">Nice composition and choice fo B&amp;W. I wanted to do something similar, but couldn''t find the time.</td>', 'Nice composition and choice fo B&W. I wanted to do something similar, but couldn''t find the time.', '2004-02-15 10:44:35.000000', NULL, 1),
