(580457, 59547, 15305, '<td valign="top">Interesting shot, nice lighting, though the composition could be better. "Letting Go" message is not contained in the picture itself.</td>', 'Interesting shot, nice lighting, though the composition could be better. "Letting Go" message is not contained in the picture itself.', '2004-02-15 10:50:14.000000', NULL, 1),
(580471, 59020, 10918, '<td valign="top">I can really relate to the emotion in this shot.</td>', 'I can really relate to the emotion in this shot.', '2004-02-15 11:18:39.000000', NULL, 1),
(580473, 59185, 10918, '<td valign="top">Is that a real Franklin?</td>', 'Is that a real Franklin?', '2004-02-15 11:19:42.000000', NULL, 1),
(580520, 59465, 14620, '<td valign="top">This is what first popped into my head when I heard "Letting Go"  I like this shot quite a bit. It gives a great feeling of Glee!  My only suggestion is to have maybe cropped it a little closer to the main subject.  But overall, very nice!</td>', 'This is what first popped into my head when I heard "Letting Go"  I like this shot quite a bit. It gives a great feeling of Glee!  My only suggestion is to have maybe cropped it a little closer to the main subject.  But overall, very nice!', '2004-02-15 12:24:38.000000', NULL, 1),
(580521, 58837, 14620, '<td valign="top">This is a very pretty shot.  I really like your interpretation of the challenge.  Beautiful colors and subject.  She looks like she''s floating, very graceful.</td>', 'This is a very pretty shot.  I really like your interpretation of the challenge.  Beautiful colors and subject.  She looks like she''s floating, very graceful.', '2004-02-15 12:26:17.000000', NULL, 1),
(580524, 58843, 14620, '<td valign="top">I very much like the lighting and symmetry of this photo.  Maybe could''ve used just a little, tiny bit more lighting up near the face and upper body as you lose a little detail there.  But overall, It''s an interesting picture and a nice take on the challenge.</td>', 'I very much like the lighting and symmetry of this photo.  Maybe could''ve used just a little, tiny bit more lighting up near the face and upper body as you lose a little detail there.  But overall, It''s an interesting picture and a nice take on the challenge.', '2004-02-15 12:30:12.000000', NULL, 1),
(580535, 59135, 11653, '<td valign="top">I like the emotion you captured on his face.</td>', 'I like the emotion you captured on his face.', '2004-02-15 12:44:09.000000', NULL, 1),
(580536, 59644, 11653, '<td valign="top">Great idea and capture. Left upper corner is a bit distracting.</td>', 'Great idea and capture. Left upper corner is a bit distracting.', '2004-02-15 12:46:01.000000', NULL, 1),
(580537, 59658, 11653, '<td valign="top">Nice color and details.</td>', 'Nice color and details.', '2004-02-15 12:48:04.000000', NULL, 1),
