(580541, 59465, 11653, '<td valign="top">Fun shot.</td>', 'Fun shot.', '2004-02-15 12:54:29.000000', NULL, 1),
(580542, 58958, 11653, '<td valign="top">Nice clarity and colorts. Cropping out the blue/green/yellow edges would have focused more attention on the baby''s face.</td>', 'Nice clarity and colorts. Cropping out the blue/green/yellow edges would have focused more attention on the baby''s face.', '2004-02-15 12:56:53.000000', NULL, 1),
(580543, 59542, 11653, '<td valign="top">Very touching photo.</td>', 'Very touching photo.', '2004-02-15 12:59:10.000000', NULL, 1),
(580544, 59687, 63, '<td valign="top">I have not seen one of these in a long time.  Great idea.   (8)</td>', 'I have not seen one of these in a long time.  Great idea.   (8)', '2004-02-15 13:04:31.000000', NULL, 1),
(580546, 59433, 63, '<td valign="top">Great frame, hope you tell how you did it. Don''t abandon the medium format completely, the big prints are hard to beat. (8)</td>', 'Great frame, hope you tell how you did it. Don''t abandon the medium format completely, the big prints are hard to beat. (8)', '2004-02-15 13:13:16.000000', NULL, 1),
(580563, 59287, 12252, '<td valign="top">Perfectly fits the theme; wonderful sharp focus on the hand (well, most of it!), the balloon is captured perfectly to suggest flight, and the background is excellent so my eyes stay on the subject. Giving it a 9 and have to believe it''s a top ten (top five?) finisher!</td>', 'Perfectly fits the theme; wonderful sharp focus on the hand (well, most of it!), the balloon is captured perfectly to suggest flight, and the background is excellent so my eyes stay on the subject. Giving it a 9 and have to believe it''s a top ten (top five?) finisher!', '2004-02-15 13:58:35.000000', NULL, 1),
(580564, 59666, 12252, '<td valign="top">Guess it says it all right in this image... &lt;sigh&gt; Nit -- the reflection of the ring on the background, and some noise on the background. But this is a top ten finisher for sure! Of all the ring submissions, this is clearly the best.  I''m giving it a 9</td>', 'Guess it says it all right in this image... <sigh> Nit -- the reflection of the ring on the background, and some noise on the background. But this is a top ten finisher for sure! Of all the ring submissions, this is clearly the best.  I''m giving it a 9', '2004-02-15 13:59:47.000000', NULL, 1),
(580568, 59068, 12252, '<td valign="top">I really like this image, especially in b&amp;w. Looks like a scene from an old ''40s movie. She''s leaving, but somehow, before the end of the movie, they''re going to get back together! Wish the rails weren''t blown out but that''s a nit. Gave this an 8</td>', 'I really like this image, especially in b&w. Looks like a scene from an old ''40s movie. She''s leaving, but somehow, before the end of the movie, they''re going to get back together! Wish the rails weren''t blown out but that''s a nit. Gave this an 8', '2004-02-15 14:02:10.000000', NULL, 1),
(580569, 59560, 12252, '<td valign="top">How''d you DO that??? Can''t wait to find out...</td>', 'How''d you DO that??? Can''t wait to find out...', '2004-02-15 14:03:34.000000', NULL, 1),
(580570, 59112, 12252, '<td valign="top">This had to be hard to pull off. The "problem" with this image, for me, is that too much of it has to be out of focus. Technically it''s wonderful, but visually it''s hard to keep looking at it.</td>', 'This had to be hard to pull off. The "problem" with this image, for me, is that too much of it has to be out of focus. Technically it''s wonderful, but visually it''s hard to keep looking at it.', '2004-02-15 14:05:19.000000', NULL, 1),
(580572, 59687, 12252, '<td valign="top">Tasteless</td>', 'Tasteless', '2004-02-15 14:05:54.000000', NULL, 1),
