(582886, 59667, 3540, '<td valign="top">A little hot on the hand and the blue has gotten a little funky grain going on too.  I also don''t like the blue cast on the candy corns.</td>', 'A little hot on the hand and the blue has gotten a little funky grain going on too.  I also don''t like the blue cast on the candy corns.', '2004-02-17 03:49:40.000000', NULL, 1),
(582888, 59068, 3540, '<td valign="top">The hot handrails on the bridge are totally distracting.  Good theme to this picture, but I think its a little too dark and maybe a little oversharpened.  Something just doesn''t seem right here.</td>', 'The hot handrails on the bridge are totally distracting.  Good theme to this picture, but I think its a little too dark and maybe a little oversharpened.  Something just doesn''t seem right here.', '2004-02-17 03:58:13.000000', NULL, 1),
(582891, 59375, 16362, '<td valign="top">good photo very nice lighting</td>', 'good photo very nice lighting', '2004-02-17 04:14:58.000000', NULL, 1),
(582903, 59660, 17081, '<td valign="top">interesting shot, but would have been better or at least more in line with the theme if the streaks were behind the car.</td>', 'interesting shot, but would have been better or at least more in line with the theme if the streaks were behind the car.', '2004-02-17 05:18:37.000000', NULL, 1),
