(584827, 59658, 11897, '<td valign="top">You were my choice for first, but I wasn''t far off.<br/>Well done.<br/>Paul.</td>', 'You were my choice for first, but I wasn''t far off.Well done.Paul.', '2004-02-18 07:05:50.000000', NULL, 0),
