(585594, 59666, 12095, '<td valign="top">This was one of my favorites in the challenge. I thought it was very well done and should have placed a lot higher.  I think the fact that a lot of people used rings caused your score to suffer. I don''t think it should. This picture should of been judged in its own context. Very well shot, great lighting and interesting composition.</td>', 'This was one of my favorites in the challenge. I thought it was very well done and should have placed a lot higher.  I think the fact that a lot of people used rings caused your score to suffer. I don''t think it should. This picture should of been judged in its own context. Very well shot, great lighting and interesting composition.', '2004-02-18 12:34:33.000000', NULL, 0),
(585606, 59645, 12095, '<td valign="top">This was one of my favorites in the challenge. I don''t usually like the kid entries in the challenges since most are snapshots that don''t fit the challenge but this one fits the challenge very well and is very artistically done.  Great use of muted color. I like the mood this picture projects, the expression on your daughters face and the butterfly. I had hoped it would have won a ribbon.</td>', 'This was one of my favorites in the challenge. I don''t usually like the kid entries in the challenges since most are snapshots that don''t fit the challenge but this one fits the challenge very well and is very artistically done.  Great use of muted color. I like the mood this picture projects, the expression on your daughters face and the butterfly. I had hoped it would have won a ribbon.', '2004-02-18 12:42:20.000000', NULL, 0),
(585628, 59654, 13669, '<td valign="top">Wow you got scammed.  Seriuosly tho, I thought you would have placed much better, but then again, im bias towards B&amp;W.</td>', 'Wow you got scammed.  Seriuosly tho, I thought you would have placed much better, but then again, im bias towards B&W.', '2004-02-18 12:52:10.000000', NULL, 0),
(585639, 58978, 13669, '<td valign="top">Too bad your image was soo small.  Its funny how yours placed the way it did, and the winning photo were similar, guess size does matter hehehe.</td>', 'Too bad your image was soo small.  Its funny how yours placed the way it did, and the winning photo were similar, guess size does matter hehehe.', '2004-02-18 12:55:45.000000', NULL, 0),
(585705, 58923, 16362, '<td valign="top">are you women hater!!?? i dont llike women haters</td>', 'are you women hater!!?? i dont llike women haters', '2004-02-18 13:18:19.000000', NULL, 0),
(585719, 59658, 10437, '<td valign="top">So well deserved ribbon, congratulations!</td>', 'So well deserved ribbon, congratulations!', '2004-02-18 13:21:45.000000', NULL, 0),
(585836, 59645, 2223, '<td valign="top">Just want to thank all who took time to comment on my entry. My daughters level of patience is very low, so i got what i could out of her and thank her for the time she gave me. If i could have done it differently, i would have changed her position against the wall so those annoying bumps could have been avoided and would have had her keep her eyes open. About the butterfly...try finding a live one in the middle of winter in NY. Still i am excited to have gotten to 6th place.</td>', 'Just want to thank all who took time to comment on my entry. My daughters level of patience is very low, so i got what i could out of her and thank her for the time she gave me. If i could have done it differently, i would have changed her position against the wall so those annoying bumps could have been avoided and would have had her keep her eyes open. About the butterfly...try finding a live one in the middle of winter in NY. Still i am excited to have gotten to 6th place.', '2004-02-18 13:50:10.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(585948, 59374, 1570, '<td valign="top">i loved this picture, sorry didn''t have a chance to comment during the challenge... i would''ve cropped just below the nose though...</td>', 'i loved this picture, sorry didn''t have a chance to comment during the challenge... i would''ve cropped just below the nose though...', '2004-02-18 14:27:13.000000', NULL, 0),
(585957, 59046, 1570, '<td valign="top">i loved this picture and gave it a six, sorry didn''t have a chance to comment during the challenge... breathtaking... pun intended...</td>', 'i loved this picture and gave it a six, sorry didn''t have a chance to comment during the challenge... breathtaking... pun intended...', '2004-02-18 14:32:50.000000', NULL, 0),
(586009, 59062, 13602, '<td valign="top">Congratulations! this is a well deserved win and as someone said before me, I think it''s about time you go pro :) Incredible how someone actualy gave this a 2 and a bounch of 3''s tho.</td>', 'Congratulations! this is a well deserved win and as someone said before me, I think it''s about time you go pro :) Incredible how someone actualy gave this a 2 and a bounch of 3''s tho.', '2004-02-18 14:59:58.000000', NULL, 0),
(586030, 58625, 14863, '<td valign="top">It''s so weird--I probably proofread this thing like 100 times and i never caught that extra "is" :D</td>', 'It''s so weird--I probably proofread this thing like 100 times and i never caught that extra "is" :D', '2004-02-18 15:07:34.000000', NULL, 0),
(586515, 59654, 12151, '<td valign="top">I agree- this was my top vote for this challenge.  Don''t let rankings discourage you.</td>', 'I agree- this was my top vote for this challenge.  Don''t let rankings discourage you.', '2004-02-18 18:47:56.000000', NULL, 0),
(586523, 59068, 9906, '<td valign="top">From the Critique Club<br/> <br/>This is one of those shots that I can not just sit down and write up a critique for.  Each time I look at it I pick up a little more than the last time.  I see another subtle nuance.  This, to me, is a sign of a very good, if not great, piece!<br/> <br/>My very first impression was that this was overly sharp and too contrasty.  After a moment I realized that you have attained an almost surreal feeling with this combination.  My next thought was that the darks are too dark and the highlights are too light, but again after a moment I realize that this all combines to give the overall feeling of moving from the here and now to the beyond.<br/> <br/>Your foreground is very crisp and clear.  The horizontal lines of the brick path give it a very ''base'' feel, like a starting point.  The rest of the lines lead your eye up and over the bridge into the unknown.  You''ve accentuated this feeling with the very dark background and the very light lines of the bridge.  This gives the bridge a feeling of a transition from the base or now into the unknown and shady future.<br/> <br/>All in all a very compelling photo which implies a story.  You don''t know the details of the story, but you know that there is a change in it.<br/> <br/>Kudos on this!<br/>TC</td>', 'From the Critique Club This is one of those shots that I can not just sit down and write up a critique for.  Each time I look at it I pick up a little more than the last time.  I see another subtle nuance.  This, to me, is a sign of a very good, if not great, piece! My very first impression was that this was overly sharp and too contrasty.  After a moment I realized that you have attained an almost surreal feeling with this combination.  My next thought was that the darks are too dark and the highlights are too light, but again after a moment I realize that this all combines to give the overall feeling of moving from the here and now to the beyond. Your foreground is very crisp and clear.  The horizontal lines of the brick path give it a very ''base'' feel, like a starting point.  The rest of the lines lead your eye up and over the bridge into the unknown.  You''ve accentuated this feeling with the very dark background and the very light lines of the bridge.  This gives the bridge a feeling of a transition from the base or now into the unknown and shady future. All in all a very compelling photo which implies a story.  You don''t know the details of the story, but you know that there is a change in it. Kudos on this!TC', '2004-02-18 18:55:22.000000', NULL, 0),
(586574, 59542, 10818, '<td valign="top">It was already a very moving photo, after reading the comment, I need a tissue.  **sniff**</td>', 'It was already a very moving photo, after reading the comment, I need a tissue.  **sniff**', '2004-02-18 19:17:24.000000', NULL, 0),
(586610, 59062, 11793, '<td valign="top">nice job</td>', 'nice job', '2004-02-18 19:35:52.000000', NULL, 0),
(586923, 59635, 14608, '<td valign="top">Thank everyone for a lot of good coments and support. I am very happy to score that high.<br/>Nothing was done on photoshop,just run through neatimage.  That why snow looks little bit funny.<br/>And I will try not to put borders anymore:)</td>', 'Thank everyone for a lot of good coments and support. I am very happy to score that high.Nothing was done on photoshop,just run through neatimage.  That why snow looks little bit funny.And I will try not to put borders anymore:)', '2004-02-18 21:59:14.000000', NULL, 0),
(586969, 59654, 11793, '<td valign="top">its a great image - lighten up the eyes maybe - or a glint...</td>', 'its a great image - lighten up the eyes maybe - or a glint...', '2004-02-18 22:34:31.000000', NULL, 0),
